  /*
    <div class="oss-upload-item {{if this.error 'oss-upload-item--errored'}}">
    {{#if this.shouldDisplayPreview}}
      <div class="upf-badge upf-badge--shape-round upf-badge--size-md" style={{this.dynamicBackgroundImage}}></div>
    {{else}}
      <OSS::Badge @icon={{this.icon}} />
    {{/if}}
  
    <div class="fx-row fx-1 fx-malign-space-between fx-xalign-center">
      <div class="fx-col fx-1 fx-gap-px-3">
        <span class="font-color-gray-900 text-ellipsis padding-right-px-12" data-control-name="upload-item-filename">
          {{this.filename}}
        </span>
  
        {{#if this.error}}
          <span class="font-color-error-500">{{t "oss-components.upload-area.errors.server"}}</span>
        {{else if this.filesize}}
          <span class="font-color-gray-500" data-control-name="upload-item-filesize">
            {{this.filesize}}
          </span>
        {{/if}}
      </div>
  
      <div class="fx-row fx-gap-px-6 fx-xalign-center">
        {{#if this.uploading}}
          <div class="oss-upload-item__loader" style={{this.loaderStyle}}>
            <div class="value">
              {{this.uploadProgress}}
            </div>
          </div>
        {{else}}
          {{#if this.error}}
            <span
              class="fx-row fx-gap-px-6 font-color-gray-500 fx-xalign-center"
              role="button"
              data-control-name="upload-item-try-again-button"
              {{on "click" this.performUpload}}
            >
              <OSS::Icon @icon="fa-redo" />
              {{t "oss-components.upload-area.errors.try_again"}}
            </span>
          {{else}}
            <OSS::Button
              @icon="far fa-pen"
              @square={{true}}
              data-control-name="upload-item-edit-button"
              {{on "click" @onEdition}}
              {{enable-tooltip title=(t "oss-components.upload-area.tooltips.edit") placement="top"}}
            />
            <OSS::Button
              @icon="far fa-eye"
              @square={{true}}
              data-control-name="upload-item-view-button"
              {{on "click" (fn this.viewItem this.fileUrl)}}
              {{enable-tooltip title=(t "oss-components.upload-area.tooltips.view")}}
            />
          {{/if}}
  
          <OSS::Button
            @icon="far fa-trash"
            @square={{true}}
            data-control-name="upload-item-remove-button"
            {{on "click" @onDeletion}}
            {{enable-tooltip title=(t "oss-components.upload-area.tooltips.delete") placement="top"}}
          />
        {{/if}}
      </div>
    </div>
  </div>
  */
